// Some portions generated by Claude
import test from "node:test";
import assert from "node:assert/strict";
import { readdirSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

// The explorer renders repository data (labels, literals, IRIs) that the Workbench must never inject as HTML, and it
// must only talk to the Workbench itself (same-origin, relative URLs), never to a hard-coded host. This mirrors
// WorkbenchFrontendSecurityTest for the lit-html pages.
const sourceDir = fileURLToPath(new URL("../../../main/frontend/graph-explorer/", import.meta.url));
const sources = readdirSync(sourceDir).filter((name) => /\.(ts|tsx)$/.test(name));

test("the explorer never injects HTML strings into the DOM", () => {
  for (const name of sources) {
    const source = readFileSync(sourceDir + name, "utf8");
    assert.doesNotMatch(source, /dangerouslySetInnerHTML/, name);
    assert.doesNotMatch(source, /\.innerHTML\s*=/, name);
    assert.doesNotMatch(source, /insertAdjacentHTML/, name);
  }
});

test("the explorer only fetches Workbench-relative URLs", () => {
  for (const name of sources) {
    const source = readFileSync(sourceDir + name, "utf8");
    for (const match of source.matchAll(/fetch\(\s*([`'"])([^`'"]*)\1/g)) {
      assert.doesNotMatch(match[2], /^https?:/, `${name}: ${match[2]}`);
    }
    assert.doesNotMatch(source, /query\.wikidata\.org|qlever\.dev|\/api\/(query|local-config|entity-search|predicate-label)/, name);
  }
});
